(44211, 'Malachi 3:18', 'Malachi', 3, 18, 'او بيا به تاسو د صادقانو او بدعملو په اَنجام کښې فرق وګورئ، او هم به تاسو د هغوئ اَنجام کښې فرق وګورئ څوک چې د خُدائ پاک خِدمت کوى او څوک يې چې نۀ کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/malachi3_verse_18.mp3', '', 1761754199, 1761754199),
(44212, 'Psalms 94:1', 'Psalms', 94, 1, 'ای څښتنه، ته یې خدای غچ اخیستونکی ای غچ اخیستونکیه خدایه، وښایه ته خپل جلال!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_1.mp3', '', 1761754199, 1761754199),
(44213, 'Psalms 94:2', 'Psalms', 94, 2, 'ای د نړۍ قاضي راپاڅېږه ته ورسوه د خپلو بدو عملونو په سزا مغروران!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_2.mp3', '', 1761754199, 1761754199),
(44214, 'Psalms 94:3', 'Psalms', 94, 3, 'ترڅو به بدکاران ای څښتنه بدکاران به خوشحالي کوي تر کومه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_3.mp3', '', 1761754199, 1761754199),
(44215, 'Psalms 94:4', 'Psalms', 94, 4, 'هغوی د کبر او غرور غټې خبرې کوي ټول بد‌کرداره خلک لافې وهي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_4.mp3', '', 1761754199, 1761754199),
(44216, 'Psalms 94:5', 'Psalms', 94, 5, 'ستا خلک تر‌پښو لاندې کوي څښتنه هغوی کړي ظلم ستا په خپلو خلکو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_5.mp3', '', 1761754199, 1761754199),
(44217, 'Psalms 94:6', 'Psalms', 94, 6, 'بل ځایي خلک او کونډې وژني هم یتیمان قتلوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_6.mp3', '', 1761754199, 1761754199),
(44218, 'Psalms 94:7', 'Psalms', 94, 7, 'وایي هغوی چې څښتن نه ویني مونږ نه یې پام کیږي مونږ ته د یعقوب د خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_7.mp3', '', 1761754199, 1761754199),
(44219, 'Psalms 94:8', 'Psalms', 94, 8, 'ای د قوم بې‌عقلو خلکو پوه شئ! کله به تاسو هوښیارېږئ ساده‌ګانو خلکو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_8.mp3', '', 1761754199, 1761754199),
(44220, 'Psalms 94:9', 'Psalms', 94, 9, 'هغه چې مونږ ته یې راکړی دی غوږ ایا هغه په خپله نه اوري څه؟ هغه چې سترګې پیدا کړې دي ایا هغه په خپله نه ویني څه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_9.mp3', '', 1761754199, 1761754199),
(44221, 'Psalms 94:10', 'Psalms', 94, 10, 'څوک چې په خپله سموي قومونه نو دوی ته نه شي ورکولای سزا؟ هغه چې خپله دی استاذ د ټولو نو ایا نه لري په خپله پوهه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_10.mp3', '', 1761754199, 1761754199),
(44222, 'Psalms 94:11', 'Psalms', 94, 11, 'څښتن پوهیږي د انسان په خیالو هغه پوهیږي چې خیالونه یې باطل او پوچ دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_11.mp3', '', 1761754199, 1761754199),
(44223, 'Psalms 94:12', 'Psalms', 94, 12, 'بختور دی هغه څوک چې ته یې سموې، څښتنه ورته تعلیم د خپل شریعت ورکوې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_12.mp3', '', 1761754199, 1761754199),
(44224, 'Psalms 94:13', 'Psalms', 94, 13, 'ورکوې ورته ارام په سختو ورځو کې ته ترڅو چې کنده ویستل کیږي شریرانو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_13.mp3', '', 1761754199, 1761754199),
(44225, 'Psalms 94:14', 'Psalms', 94, 14, 'ځکه څښتن به خپل خلک نه کاندي رد او نه به چېرته خپل ولس پرېږدي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_14.mp3', '', 1761754199, 1761754199),
(44226, 'Psalms 94:15', 'Psalms', 94, 15, 'تر‌سره کیږي قضاوت به د انصاف او عدالت سره سم او ټول نېکان به یې کوي پیروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_15.mp3', '', 1761754199, 1761754199),
(44227, 'Psalms 94:16', 'Psalms', 94, 16, 'څوک به زما دپاره پاڅي په خلاف د بدکارانو خلکو؟ څوک به زما دپاره ودریږي په ضد د شریرانو خلکو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_16.mp3', '', 1761754199, 1761754199),
(44228, 'Psalms 94:17', 'Psalms', 94, 17, 'که مرستندوی زما نه وای څښتن نو زه به زر ومه ډوب شوی په چوپتیا د مرګي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_17.mp3', '', 1761754199, 1761754199),
(44229, 'Psalms 94:18', 'Psalms', 94, 18, 'کله چې ما وویل: «غورځېږمه زه څښتنه ستا تلپاتې مینې راټینګ کړمه زه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_18.mp3', '', 1761754199, 1761754199),
(44230, 'Psalms 94:19', 'Psalms', 94, 19, 'د زړه د زیاتو اندېښنو په منځ کې ستا تسلۍ ماته خوښي راوړله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_19.mp3', '', 1761754199, 1761754199),
(44231, 'Psalms 94:20', 'Psalms', 94, 20, 'هغو قاضیانو فاسدانو سره نه کړې یاري چې د قانون په نامه بې‌انصافي کوي دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_20.mp3', '', 1761754199, 1761754199),
(44232, 'Psalms 94:21', 'Psalms', 94, 21, 'چې په شریکه د نېکانو د وژلو دسیسې جوړوي محکوموي بې‌ګناه خلک په مرګ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_21.mp3', '', 1761754199, 1761754199),
(44233, 'Psalms 94:22', 'Psalms', 94, 22, 'خو څښتن شولو پناه ګاه زما زما خدای زما د پټېدو دپاره کلکه کلا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_22.mp3', '', 1761754199, 1761754199),
(44234, 'Psalms 94:23', 'Psalms', 94, 23, 'خدای به راوګرځوي بېرته هغو باندې خپلې بدۍ هغوی تباه به کړي د خپلو ګناهونو په خاطر زمونږ څښتن خدای به تباه کړي هغوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms94_verse_23.mp3', '', 1761754199, 1761754199),
(44235, 'Psalms 5:1', 'Psalms', 5, 1, 'واوره ای څښتنه ته ګفتار زما وکړه پام په اسوېلو زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_1.mp3', '', 1761754199, 1761754199),
(44236, 'Psalms 5:2', 'Psalms', 5, 2, 'ای زما پاچا ای زما خدایه! واوره ته فریاد زما کومک لره ځکه چې زه تاته دعا کومه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_2.mp3', '', 1761754199, 1761754199),
(44237, 'Psalms 5:3', 'Psalms', 5, 3, 'هر سهار کې اواز اورې ته زما هر سهار کې زه کوم درته دعا انتظار د ځواب کړمه زه له تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_3.mp3', '', 1761754199, 1761754199),
(44238, 'Psalms 5:4', 'Psalms', 5, 4, 'نه یې داسې خدای چې خوښوې بدکاري اوسېدی نه شي له تا سره هېڅ ډول ګناهکار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_4.mp3', '', 1761754199, 1761754199),
(44239, 'Psalms 5:5', 'Psalms', 5, 5, 'ستا حضور کې کبرجن ودرېدی نه شي ته نفرت لرې له ټولو بدکارانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_5.mp3', '', 1761754199, 1761754199),
(44240, 'Psalms 5:6', 'Psalms', 5, 6, 'ټول دروغجن هلاکوې ته جابران او چلبازان هم سپکوې ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_6.mp3', '', 1761754199, 1761754199),
(44241, 'Psalms 5:7', 'Psalms', 5, 7, 'خو په سبب د ستا له زیاتې او تلپاتې مینې زه به درشمه ستا کور ته او ستا له وېرې په سجده به شمه ستا سپېڅلي کور ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_7.mp3', '', 1761754199, 1761754199),
(44242, 'Psalms 5:8', 'Psalms', 5, 8, 'ای څښتنه، زما ډېر دي دښمنان لارښوونه راته وکړه چې زه وکړم ستا رضا زما مخې ته کړه خپله لار صفا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_8.mp3', '', 1761754199, 1761754199),
(44243, 'Psalms 5:9', 'Psalms', 5, 9, 'ځکه چې نشته رښتیا د هغوی په خوله کې او زړونه یې غواړي د نورو بربادي او ژبې یې ډکې دي د ریاکارۍ او چل او وله څخه ستوني یې خلاص دي لکه د قبر په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_9.mp3', '', 1761754199, 1761754199),
(44244, 'Psalms 5:10', 'Psalms', 5, 10, 'ته سزا هغوی ته ورکړه او محکوم یې کړه ای خدایه چې په خپلو دسیسو خپله برباد شي په سبب د دوی د ډېرو ګناهونو په سبب د سرکښۍ ستا مقابل کې هغوی وشړه بیخي له خپل حضوره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_10.mp3', '', 1761754199, 1761754199),
(44245, 'Psalms 5:11', 'Psalms', 5, 11, 'پرېږده چې وي هغه ټول کسان خوشحال څوک چې ځان په تا کې پناه مومي پرېږده چې مدام د خوشحالۍ سندرې ووایي وساته هغوی چې کوي مینه ستا د نوم سره په رښتیا چې له امله ستا خوشحال وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_11.mp3', '', 1761754199, 1761754199),
(44246, 'Psalms 5:12', 'Psalms', 5, 12, 'ای څښتنه، ورکوې ته برکت نېکانو ته کړي به ستا رحم حفاظت د هغوی لکه د سپر په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms5_verse_12.mp3', '', 1761754199, 1761754199),
(44247, 'Amos 6:1', 'Amos', 6, 1, 'افسوس ستاسو په حال چې په صهیون کې ارام ژوند تېروئ او تاسو چې په سامره کې په امن کې یئ. ای د اسراییلو د ډېر لوی قوم مشرانو، چې خلک درته د مرستې په خاطر درځي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_1.mp3', '', 1761754199, 1761754199),
(44248, 'Amos 6:2', 'Amos', 6, 2, 'لاړ شئ او د کلنه ښار ته وګورئ. بیا د حمات لوی ښار ته لاړ شئ او بیا د فلسطین ښار جت ته لاړ شئ. ایا تاسو د یهودا او اسراییلو د پاچاهیو څخه ښه یئ؟ ایا د هغوی سیمه ستاسو د سیمې څخه لویه ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_2.mp3', '', 1761754199, 1761754199),
(44249, 'Amos 6:3', 'Amos', 6, 3, 'تاسو دا نه منله چې د مصیبت هغه ورځ راروانه ده، خو ستاسو د خپلو بدو عملونو له امله به د ظلم او زیاتي حکومت قایم شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_3.mp3', '', 1761754199, 1761754199),
(44250, 'Amos 6:4', 'Amos', 6, 4, 'افسوس ستاسو په حال چې د فیل په غاښونو باندې په ښکلي کړای شویو تختونو او نرمو توشکونو باندې ناست یئ او د چاغو خوسيو او وریو په غوښو باندې مېلې کوئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_4.mp3', '', 1761754199, 1761754199),
(44251, 'Amos 6:5', 'Amos', 6, 5, 'تاسو دا خوښوئ چې د داود په شان سندرې جوړې کړئ او د چنګونو د ساز سره یې ووایئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_5.mp3', '', 1761754199, 1761754199),
(44252, 'Amos 6:6', 'Amos', 6, 6, 'تاسو په جامونو جامونو شراب څښئ او ډېر ښه عطر کاروئ، خو د اسراییلو په تباهۍ باندې ویر نه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_6.mp3', '', 1761754199, 1761754199),
(44253, 'Amos 6:7', 'Amos', 6, 7, 'نو تاسو به لومړني خلک یئ چې په جلاوطنۍ باندې به ځئ. ستاسو اخترونه او مېلمستیاوې به پای ته ورسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_7.mp3', '', 1761754199, 1761754199),
(44254, 'Amos 6:8', 'Amos', 6, 8, 'مطلق قادر څښتن تعالی په خپل ذات باندې قسم خوړلی دی او داسې وایي: «زه د اسراییلو د غرور نه کرکه لرم او د هغوی د عیاشۍ کلاګانې مې بدې راځي. زه به د هغوی پایتخت او هرڅه چې په کې دي، هغه به دښمنانو ته ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_8.mp3', '', 1761754199, 1761754199),
(44255, 'Amos 6:9', 'Amos', 6, 9, 'که په یوې کورنۍ کې لس تنه هم پاتې وي، نو هغوی به مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_9.mp3', '', 1761754199, 1761754199),
(44256, 'Amos 6:10', 'Amos', 6, 10, 'د مړ شوي کس کوم خپلوان چې د جنازې د مراسمو مشري کوي، هغه به هغه مړی د کور نه یوسي. نو دا خپلوان به د هغه چا نه چې ژوندی پاتې شوی دی، پوښتنه کوي: «ایا ستاسو په کور کې نور څوک شته؟» نو هغه به ځواب ورکړي: «نه!» نو هغه خپلوان به یې ووایي: «غلی شه! مونږ باید احتیاط وکړو چې د څښتن نوم هم په خوله وانخلو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_10.mp3', '', 1761754199, 1761754199),
(44257, 'Amos 6:11', 'Amos', 6, 11, 'نو کله چې څښتن حکم وکړي، لوی او واړه کورونه دواړه دې د خاورو سره خاورې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_11.mp3', '', 1761754199, 1761754199),
(44258, 'Amos 6:12', 'Amos', 6, 12, 'ایا اسونه په ګټانو باندې ځغلېدلی شي؟ ایا څوک په بحر کې په غویانو باندې قلبه کولای شي؟ خو تاسو انصاف په زهرو او د عدالت خوږه مېوه مو ترخه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_12.mp3', '', 1761754199, 1761754199),
(44259, 'Amos 6:13', 'Amos', 6, 13, 'تاسو د لودیبار د ښارګوټي په نیولو خوشحالي کوئ. تاسو لافې وهئ او وایئ: «مونږ دومره تکړه یو چې د کارناییم ښارګوټی هم نیولی شو.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_13.mp3', '', 1761754199, 1761754199),
(44260, 'Amos 6:14', 'Amos', 6, 14, 'مطلق قادر څښتن خدای په خپله وایي: «ای د اسراییلو خلکو، زه به یو پردی لښکر درولېږم چې ستاسو وطن ونیسي. هغوی به په شمال کې د حمات د غاښي نه نیولې په جنوب کې د عربه تر ویالې پورې په تاسو باندې ظلم کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos6_verse_14.mp3', '', 1761754199, 1761754199),
(44261, 'Ezekiel 43:1', 'Ezekiel', 43, 1, 'بیا هغه سړي زه هغې دروازې ته بوتلم چې ختیځې خواته مخامخ وه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_1.mp3', '', 1761754199, 1761754199),
(44262, 'Ezekiel 43:2', 'Ezekiel', 43, 2, 'او ما ولیدل چې د ختیځې خوا نه د اسراییلو د خدای جلال راروان دی. د خدای د راتلو اواز د تېزو اوبو د غرهار په شان ؤ او ځمکه د هغه د جلال څخه رڼا شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_2.mp3', '', 1761754199, 1761754199),
(44263, 'Ezekiel 43:3', 'Ezekiel', 43, 3, 'دا رویا د هغې رویا په شان وه چې ما هغه وخت لیدلې وه چې کله خدای د اورشلیم د منځه وړلو دپاره راغلی ؤ او د هغې رویا په شان وه چې ما د خابور د سیند په غاړه لیدلې وه. بیا زه د وېرې نه پړمخې پرېوتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_3.mp3', '', 1761754199, 1761754199),
(44264, 'Ezekiel 43:4', 'Ezekiel', 43, 4, 'د څښتن جلال د ختیځې دروازې له لارې تېر شو او د هغه کور ته ننوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_4.mp3', '', 1761754199, 1761754199),
(44265, 'Ezekiel 43:5', 'Ezekiel', 43, 5, 'بیا د څښتن روح زه اوچت کړم، دنننۍ حوېلۍ ته یې بوتلم او ما ولیدل چې د څښتن کور د هغه د جلال نه ډک شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_5.mp3', '', 1761754199, 1761754199),
(44266, 'Ezekiel 43:6', 'Ezekiel', 43, 6, 'په داسې حال کې چې هغه سړی زما په څنګ کې ولاړ ؤ، ما د څښتن اواز واورېده چې دننه د خپل کور نه یې زما سره خبرې کولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_6.mp3', '', 1761754199, 1761754199),
(44267, 'Ezekiel 43:7', 'Ezekiel', 43, 7, 'هغه وویل: «ای فاني انسانه، دا زما تخت او د پښو د ایښودلو ځای دی. زه به دلته د اسراییلو د قوم په منځ کې د تل دپاره اوسېږم. نور به د اسراییلو قوم او د هغوی پاچاهان نورو خدایانو ته په عبادت کولو یا په دې ځای کې د خپلو مړو پاچاهانو په زیارت کولو سره زما سپکاوی ونه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_7.mp3', '', 1761754199, 1761754199),
(44268, 'Ezekiel 43:8', 'Ezekiel', 43, 8, 'پاچاهانو خپلې ماڼۍ زما د کور په څنګ کې جوړې کړلې چې زما او د هغوی په منځ کې یوازې یو دېوال ؤ. هغوی د خپلو د کرکې وړ کارونو سره زما د سپېڅلي نوم بې‌عزتي وکړه او ما په خپل قهر سره هغوی له منځه یووړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_8.mp3', '', 1761754199, 1761754199),
(44269, 'Ezekiel 43:9', 'Ezekiel', 43, 9, 'نو اوس باید هغوی د نورو خدایانو عبادت بس کړي او د خپلو پاچاهانو زیارتونه دې لېرې کړي. که هغوی داسې وکړي، نو زه به د تل دپاره د هغوی سره واوسېږم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_9.mp3', '', 1761754199, 1761754199),
(44270, 'Ezekiel 43:10', 'Ezekiel', 43, 10, 'نو بیا څښتن وویل: «ای فاني انسانه، زما د کور په هکله د اسراییلو قوم ته ووایه چې د هغې نقشې په هکله فکر وکړي او د خپلو ګناهونو څخه وشرمیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_10.mp3', '', 1761754199, 1761754199),
(44271, 'Ezekiel 43:11', 'Ezekiel', 43, 11, 'که چېرې هغوی د خپلو ټولو بدو کارونو په سبب وشرمیږي، نو زما د کور د نقشې، تصویر، دروازې، د هغې د وتلو او ننوتلو لاره، د قوانینو او مقرراتو په هکله هغوی ته تشریح ورکړه. دا ټول شیان هغوی ته ولیکه چې هغوی یې وویني دا هرڅه څنګه تیار شوي دي، ترڅو هغوی په ټولو قوانینو باندې عمل وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_11.mp3', '', 1761754199, 1761754199),
(44272, 'Ezekiel 43:12', 'Ezekiel', 43, 12, 'زما د کور قانون دا دی. د غره په سر باندې چېرته چې زما کور دی، د هغې شاوخوا سیمه به ډېره سپېڅلې وي. ګوره، دا د زما د کور قانون دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_12.mp3', '', 1761754199, 1761754199),
(44273, 'Ezekiel 43:13', 'Ezekiel', 43, 13, '«دا د قربانۍ د ځای مساحت دی، چې په هغې کې د اندازه کولو د هغه واحد نه کار اخیستل شوی لکه څنګه چې زما په کور کې ؤ. د قربانۍ د ځای په شاوخوا کې لښتی ؤ چې پنځوس سانتي متره ژور ؤ او پنځوس سانتي متره یې سور ؤ او څنډې یې پنځه ویشت سانتي متره لوړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_13.mp3', '', 1761754199, 1761754199),
(44274, 'Ezekiel 43:14', 'Ezekiel', 43, 14, 'د قربانۍ د ځای لاندېنۍ برخې د لښتي نه تر پورتنۍ څنډې پورې یو متر لوړوالی ؤ او د څنډې سور یې پنځوس سانتي متره ؤ. د لاندېنۍ برخې څنډې نه تر منځنۍ برخې څنډې پورې یې دوه متره لوړوالی ؤ. د دې څنډې سور هم پنځوس سانتي متره ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_14.mp3', '', 1761754199, 1761754199),
(44275, 'Ezekiel 43:15', 'Ezekiel', 43, 15, 'هغه پاسنۍ برخه چې قربانۍ ورباندې سوځول کیږي، هغې هم دوه متره لوړوالی درلود. په څلورو کنجونو باندې چې کوم ښکرونه وو، هغه د پاسنۍ برخې نه اوچت وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_15.mp3', '', 1761754199, 1761754199),
(44276, 'Ezekiel 43:16', 'Ezekiel', 43, 16, 'د قربانۍ د ځای پاسنۍ برخه مربع شکله وه چې هره خوا یې شپږ شپږ متره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_16.mp3', '', 1761754199, 1761754199),
(44277, 'Ezekiel 43:17', 'Ezekiel', 43, 17, 'د پاسنۍ برخې څنډې هم د مربع شکل درلود چې هره خوا یې اووه متره وه. د دې برخې د باندینۍ څنډې سور پنځه ویشت سانتي متره ؤ. دلته یو لښتی هم ؤ چې ژوروالی یې پنځوس سانتي متره ؤ. د قربانۍ ځای ته چې کومه زینه ختلې وه، هغه ختیځې خواته وه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_17.mp3', '', 1761754199, 1761754199),
(44278, 'Ezekiel 43:18', 'Ezekiel', 43, 18, 'څښتن تعالی ماته وویل: «ای فاني انسانه، زه داسې وایم چې د قربانۍ د ځای قوانین دا دي: کله چې د قربانۍ ځای جوړ شو، نو په هغې باندې د قربانیو په سوځولو او د قرباني شویو حیواناتو د وینې په شیندلو باندې هغه وقف کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_18.mp3', '', 1761754199, 1761754199),
(44279, 'Ezekiel 43:19', 'Ezekiel', 43, 19, 'ته باید یو خوسی هغو کاهنانو ته چې لاویان او د صادوق اولاده ده، ورکړې. یوازې هغوی دا اجازه لري چې زما حضور ته راشي او زما خدمت وکړي. هغوی به دا خوسی د ګناه د نذرانې په توګه وړاندې کړي. زه څښتن تعالی داسې وایم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_19.mp3', '', 1761754199, 1761754199),
(44280, 'Ezekiel 43:20', 'Ezekiel', 43, 20, 'ته باید د هغې نه لږه وینه واخلې او هغه د قربانۍ د ځای په څلورو ښکرونو او د قربانۍ د ځای د پاسنۍ څنډې په څلورو کنجونو او د هغې د غاړو په ټولو خواو باندې وموښې. ته به د قربانۍ د ځای د پاکوالي مراسم تر سره کړې او په دې ډول به هغه پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_20.mp3', '', 1761754199, 1761754199),
(44281, 'Ezekiel 43:21', 'Ezekiel', 43, 21, 'ته به هغه خوسی چې د ګناه د قربانۍ په توګه وړاندې شوی دی، یوسې او هغه به د عبادت د ځای یعنې د څښتن د کور د ساحې نه دباندې په یو ځانګړي ځای کې چې د کور سره اړه لري، وسوځول شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_21.mp3', '', 1761754199, 1761754199),
(44282, 'Ezekiel 43:22', 'Ezekiel', 43, 22, 'بله ورځ به یو سېرلی چې کوم عیب په کې نه وي، بوځې او د ګناه د قربانۍ په توګه به یې وړاندې کړې. لکه څنګه چې د قربانۍ ځای د خوسي په وینو پاک شو، همداسې دې د سېرلي په وینو پاک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_22.mp3', '', 1761754199, 1761754199),
(44283, 'Ezekiel 43:23', 'Ezekiel', 43, 23, 'کله چې دې دا کار خلاص کړ، نو یو خوسی او یو ځوان پسه چې په دواړو کې کوم عیب نه وي، واخله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_23.mp3', '', 1761754199, 1761754199),
(44284, 'Ezekiel 43:24', 'Ezekiel', 43, 24, 'او ماته یې راوله. کاهنان به په هغو باندې مالګه وشیندي او هغه به ماته د سوځېدونکې نذرانې په توګه وړاندې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_24.mp3', '', 1761754199, 1761754199),
(44285, 'Ezekiel 43:25', 'Ezekiel', 43, 25, 'ته به اووه ورځې هره ورځ یو سېرلی د ګناه د نذرانې دپاره تیار کړې، همدارنګه یو خوسی او یو ځوان پسه چې عیب په کې نه وي، تیار کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_25.mp3', '', 1761754199, 1761754199),
(44286, 'Ezekiel 43:26', 'Ezekiel', 43, 26, 'کاهنان باید اووه ورځې د قربانۍ ځای پاک کړي او په دې ډول به هغوی دا وقف کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_26.mp3', '', 1761754199, 1761754199),
(44287, 'Ezekiel 43:27', 'Ezekiel', 43, 27, 'د اوو ورځو نه وروسته کاهنان باید هغه سوځېدونکې نذرانې او د سلامتۍ نذرانې چې خلک یې راوړي، د قربانۍ په ځای باندې وړاندې کړي. بیا به زه ستاسو نه راضي شم. ما څښتن تعالی داسې ویلي دي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel43_verse_27.mp3', '', 1761754199, 1761754199),
(44288, 'Genesis 18:1', 'Genesis', 18, 1, 'څښتن ابراهیم ته د ممري لویو ونو ته نژدې ښکاره شو. په هغه وخت کې هغه د ورځې په ګرمۍ کې د خېمې د دروازې په خوله کې ناست ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_1.mp3', '', 1761754199, 1761754199),
(44289, 'Genesis 18:2', 'Genesis', 18, 2, 'ابراهیم پورته وکتل او ویې لیدل چې هلته درې کسان ولاړ دي او چې څنګه یې هغوی ولیدل، هغه په منډه د خېمې د دروازې څخه د هغوی د لیدلو دپاره ورغی او د درناوي په خاطر ورته په ځمکه باندې پړمخې پرېوت.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_2.mp3', '', 1761754199, 1761754199),
(44290, 'Genesis 18:3', 'Genesis', 18, 3, 'هغه وویل: «ای بادارانو! مهرباني وکړئ ودرېږئ او زما د کور څخه مه تېرېږئ. زه حاضر یم چې ستاسو خدمت وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_3.mp3', '', 1761754199, 1761754199),
(44291, 'Genesis 18:4', 'Genesis', 18, 4, 'که اجازه وي، تاسو ته به لږې اوبه راوړم چې خپلې پښې ووینځئ. تاسو کولای شئ چې د دې ونې لاندې ارام وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_4.mp3', '', 1761754199, 1761754199),
(44292, 'Genesis 18:5', 'Genesis', 18, 5, 'زه به یو څه خواړه هم راوړم. هغه به تاسو ته قوت درکړي چې خپل سفر ته دوام ورکړئ. تاسو زما کور ته په راتللو سره ماته عزت راکړ. نو اجازه راکړئ چې خدمت مو وکړم.» هغوی ځواب ورکړ: «ډېر ښه، لکه څنګه چې وایې همداسې وکړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_5.mp3', '', 1761754199, 1761754199),
(44293, 'Genesis 18:6', 'Genesis', 18, 6, 'ابراهیم په ډېرې چټکۍ سره خېمې ته ننوت او ساره ته یې وویل: «زر شه او د خپلو ښو اوړو څخه درې پیمانې راواخله او ډوډۍ ورڅخه پخې کړه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_6.mp3', '', 1761754199, 1761754199),
(44294, 'Genesis 18:7', 'Genesis', 18, 7, 'بیا ابراهیم په منډه د پادې خواته ورغی او یو ښه ځوان او چاغ خوسی یې ونیوه او خپل نوکر ته یې ورکړ چې هغه ډېر زر پوخ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_7.mp3', '', 1761754199, 1761754199),
(44295, 'Genesis 18:8', 'Genesis', 18, 8, 'بیا هغه یو څه مستې، شیدې او هغه خوسی چې پوخ کړی یې ؤ، راوړ او د هغوی په مخکې یې کېښودل. کله چې هغوی ډوډۍ خوړله، ابراهیم د هغوی تر‌څنګه د یوې ونې لاندې ولاړ ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_8.mp3', '', 1761754199, 1761754199),
(44296, 'Genesis 18:9', 'Genesis', 18, 9, 'نو هغوی د ابراهیم څخه پوښتنه وکړه: «ستا ښځه ساره چېرته ده؟» هغه ځواب ورکړ: «هغه په خېمه کې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_9.mp3', '', 1761754199, 1761754199),
(44297, 'Genesis 18:10', 'Genesis', 18, 10, 'د هغو درېو کسانو څخه یو څښتن ؤ، هغه وویل: «زه به په راتلونکي کال کې په همدې وخت بېرته راشم او ستا د ښځې ساره به زوی پیدا شي.» ساره د خېمې په دروازه کې د هغه ترشا ولاړه وه او د هغوی خبرو ته یې غوږ نیولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_10.mp3', '', 1761754199, 1761754199),
(44298, 'Genesis 18:11', 'Genesis', 18, 11, 'ابراهیم او ساره ډېر زاړه وو او ساره د اولاد د راوړلو نه وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_11.mp3', '', 1761754199, 1761754199),
(44299, 'Genesis 18:12', 'Genesis', 18, 12, 'نو ساره د خپل ځان سره وخندل او ویې ویل: «اوس زه زړه یم او د کاره لوېدلې یم، ایا دا کېدای شي چې په ما باندې دا خوشحالي راشي؟ بله دا چې زما مېړه هم زوړ دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_12.mp3', '', 1761754199, 1761754199),
(44300, 'Genesis 18:13', 'Genesis', 18, 13, 'بیا څښتن د ابراهیم څخه پوښتنه وکړه: «ساره ولې وخندل او ویې ویل چې اوس خو زه زړه شوې یم، ایا دا کېدای شي چې زه اوس ماشوم وزېږوم؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_13.mp3', '', 1761754199, 1761754199),
(44301, 'Genesis 18:14', 'Genesis', 18, 14, 'ایا داسې کوم کار شته چې د څښتن دپاره ګران وي؟ لکه څنګه چې مې وویل، زه به په راتلونکي کال کې په همدې وخت بېرته راشم او ساره به زوی ولري.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_14.mp3', '', 1761754199, 1761754199),
(44302, 'Genesis 18:15', 'Genesis', 18, 15, 'ساره ډېره ووېرېدله، نو منکره شوه او ویې ویل: «ما نه دي خندلي.» خو هغه ورته وویل: «هو، تا وخندل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_15.mp3', '', 1761754199, 1761754199),
(44303, 'Genesis 18:16', 'Genesis', 18, 16, 'بیا هغه خلک پاڅېدل چې لاړ شي. هغوی ښکته د سدوم خواته وکتل او ابراهیم ورسره لاړ چې هغوی رخصت کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_16.mp3', '', 1761754199, 1761754199),
(44304, 'Genesis 18:17', 'Genesis', 18, 17, 'بیا څښتن د خپل ځان سره وویل: «څه چې زه غواړم ویې کړم هغه به د ابراهیم څخه پټ نه کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_17.mp3', '', 1761754199, 1761754199),
(44305, 'Genesis 18:18', 'Genesis', 18, 18, 'په یقین سره به د ابراهیم څخه لوی او زورور قوم جوړ شي او د ځمکې ټول قومونه به د هغه په وسیله برکت ومومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_18.mp3', '', 1761754199, 1761754199),
(44306, 'Genesis 18:19', 'Genesis', 18, 19, 'ځکه چې ما هغه غوره کړی دی چې هغه به خپلو ماشومانو او خپلې کورنۍ ته داسې لارښوونه وکړي، ترڅو د هغه څخه وروسته زما اطاعت وکړي او هغه څه وکړي چې سم او عادلانه وي، ترڅو هغه وعده چې ما د ابراهیم سره کړې ده، سرته ورسوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_19.mp3', '', 1761754199, 1761754199),
(44307, 'Genesis 18:20', 'Genesis', 18, 20, 'بیا څښتن ابراهیم ته وویل: «د سدوم او عمورې په ضد زیات تورونه موجود دي او د هغوی ګناهونه ډېر زیات شوي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_20.mp3', '', 1761754199, 1761754199),
(44308, 'Genesis 18:21', 'Genesis', 18, 21, 'اوس به زه لاندې راښکته شم چې دا معلومه کړم چې ایا د هغو تورونو په اړه چې ما اورېدلي دي، هغه رښتیا دي یا نه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_21.mp3', '', 1761754199, 1761754199),
(44309, 'Genesis 18:22', 'Genesis', 18, 22, 'هغه دوه کسان روان شول او د سدوم خوا ته لاړل، خو څښتن د ابراهیم سره پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_22.mp3', '', 1761754199, 1761754199),
(44310, 'Genesis 18:23', 'Genesis', 18, 23, 'ابراهیم څښتن ته ورنژدې شو او ویې ویل: «ایا نېک خلک به د بدکارانو سره یوځای له منځه وړې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis18_verse_23.mp3', '', 1761754199, 1761754199);